        else:
            d_center = abs(x - center[0]) + abs(y - center[1])
            if "evasion" in mode or "runner" in mode or "flee" in mode:
                v = ((4 - d_opp) * 8 if d_opp <= 4 else -d_opp, d_center, dx == 0 and dy == 0)
            elif "pursuit" in mode or "chase" in mode or "hunter" in mode:
                v = (d_opp, d_center, dx == 0 and dy == 0)
            else:
                if d_opp <= 3:
                    v = ((4 - d_opp) * 7, d_center, dx == 0 and dy == 0)
                else:
                    v = (-d_opp, d_center, dx == 0 and dy == 0)

        if bestv is None or v < bestv:
